export const dynamic = 'force-dynamic'

import { NextResponse } from 'next/server'
import { apiHandler } from '@/lib/apiHandler'
import { db } from '@/lib/db'
import { validateImportedCoordinates } from '@/lib/spatial/importCrsGuard'

// AUTO-GENERATED by api-row-sweep --apply -- column types from migrations/*.sql + name heuristics.
// pg returns bigint/numeric as string, timestamptz as Date; nullable columns carry `| null`; REVIEW.
interface ProjectRow {
  id: string
  utm_zone: string | null
  hemisphere: string | null
  datum: string | null
}

// AUTO-GENERATED by api-row-sweep --apply — column types from migrations/*.sql + name heuristics.
// pg returns bigint/numeric as string, timestamptz as Date; nullable columns carry `| null`; REVIEW.
interface SurveyPointRow {
  id: string
  project_id: string
  point_name: string | null
  easting: number | null
  northing: number | null
  elevation: number | null
  description: string | null
  code: string | null
  geom: string | null
  created_at: Date | null
  updated_at: Date | null
}
export const POST = apiHandler({ auth: true, rateLimit: { max: 60, windowMs: 60000 } }, async (request, ctx) => {
  const { projectId, points } = ctx.body as {
    projectId?: string
    points?: Array<{ easting: number; northing: number; elevation: number; name?: string }>
  }

  if (!projectId || !points || !Array.isArray(points)) {
    return NextResponse.json({ error: 'Invalid request: projectId and points array required' }, { status: 400 })
  }

  const { rows: projectRows } = await db.query<ProjectRow>(
    'SELECT id, utm_zone, hemisphere, datum FROM projects WHERE id = $1 AND user_id = $2 LIMIT 1',
    [projectId, ctx.userId]
  )

  if (projectRows.length === 0) {
    return NextResponse.json({ error: 'Project not found' }, { status: 404 })
  }

  const validPoints = points
    .filter((p) =>
      typeof p.easting === 'number' &&
      typeof p.northing === 'number' &&
      typeof p.elevation === 'number'
    )

  if (validPoints.length === 0) {
    return NextResponse.json({ error: 'No valid points provided' }, { status: 400 })
  }

  // CRS gate (blueprint §31 P0 "Validate CRS during import"): spot heights are
  // projected coordinates — reject undeclared or out-of-range data before INSERT.
  const crsCheck = validateImportedCoordinates({
    points: validPoints.map((p, i) => ({ name: p.name ?? `#${i + 1}`, x: p.easting, y: p.northing })),
    projectCrsColumns: projectRows[0],
  })
  if (!crsCheck.ok) {
    return NextResponse.json(
      {
        error: crsCheck.errors.map((e) => e.message).join(' '),
        code: crsCheck.errors[0]?.code ?? 'CRS_VALIDATION_FAILED',
        details: crsCheck.errors,
      },
      { status: 400 },
    )
  }

  // Bulk import — wrap all inserts in a single transaction so partial
  // failures don't leave orphan survey points in the database.
  // (DB best practice: multi-row writes must be atomic.)
  const inserted: SurveyPointRow[] = []
  await db.transaction(async (client) => {
    for (const p of validPoints) {
      try {
        const { rows } = await client.query<SurveyPointRow>(
          `INSERT INTO survey_points (project_id, point_type, easting, northing, elevation, name, created_by)
           VALUES ($1, $2, $3, $4, $5, $6, $7)
           ON CONFLICT (project_id, point_type, name) DO UPDATE
           SET easting = EXCLUDED.easting, northing = EXCLUDED.northing, elevation = EXCLUDED.elevation
           RETURNING *`,
          [projectId, 'spot_height', p.easting, p.northing, p.elevation, p.name || null, ctx.userId]
        )
        if (rows[0]) inserted.push(rows[0])
      } catch (err: unknown) {
        // Fallback for init-test-db schema which might use point_name and lack point_type/created_by
        if ((err as Error).message && (err as Error).message.includes('column "point_type" of relation "survey_points" does not exist')) {
          const { rows } = await client.query<SurveyPointRow>(
            `INSERT INTO survey_points (project_id, easting, northing, elevation, point_name)
             VALUES ($1, $2, $3, $4, $5)
             RETURNING *`,
            [projectId, p.easting, p.northing, p.elevation, p.name || null]
          )
          if (rows[0]) inserted.push(rows[0])
        } else {
          throw err
        }
      }
    }
  })

  return NextResponse.json({
    success: true,
    imported: inserted.length,
    points: inserted,
    ...(crsCheck.warnings.length > 0 ? { warnings: crsCheck.warnings } : {}),
  })
})
